#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

#define WIDTH 800
#define HEIGHT 600
#define MAX_DEPTH 50
#define SAMPLES 4

typedef struct {
    float x, y, z;
} Vec3;

typedef struct {
    Vec3 origin, direction;
} Ray;

typedef struct {
    Vec3 center;
    float radius;
    Vec3 color;
    int material;
} Sphere;

Vec3 add(Vec3 a, Vec3 b) { return (Vec3){a.x+b.x, a.y+b.y, a.z+b.z}; }
Vec3 sub(Vec3 a, Vec3 b) { return (Vec3){a.x-b.x, a.y-b.y, a.z-b.z}; }
Vec3 mul(Vec3 a, float t) { return (Vec3){a.x*t, a.y*t, a.z*t}; }
Vec3 cross(Vec3 a, Vec3 b) { return (Vec3){a.y*b.z-a.z*b.y, a.z*b.x-a.x*b.z, a.x*b.y-a.y*b.x}; }
float dot(Vec3 a, Vec3 b) { return a.x*b.x + a.y*b.y + a.z*b.z; }
float length_sq(Vec3 a) { return dot(a, a); }
float length(Vec3 a) { return sqrtf(length_sq(a)); }
Vec3 normalize(Vec3 a) { float l = length(a); return (Vec3){a.x/l, a.y/l, a.z/l}; }

Ray ray_create(Vec3 o, Vec3 d) {
    float l = length(d);
    return (Ray){o, normalize(d)};
}

Vec3 ray_at(Ray r, float t) { return add(r.origin, mul(r.direction, t)); }

int sphere_intersect(Ray r, Sphere s, float *t_out) {
    Vec3 oc = sub(r.origin, s.center);
    float a = length_sq(r.direction);
    float b = 2.0f * dot(oc, r.direction);
    float c = length_sq(oc) - s.radius * s.radius;
    float d = b*b - 4*a*c;
    if (d < 0) return 0;
    float t = (-b - sqrtf(d)) / (2*a);
    if (t < 0.001f) t = (-b + sqrtf(d)) / (2*a);
    if (t < 0.001f) return 0;
    *t_out = t;
    return 1;
}

Vec3 trace(Ray r, Sphere *spheres, int n_spheres, int depth) {
    float best_t = 1e30f;
    int best_i = -1;

    for (int i = 0; i < n_spheres; i++) {
        float t;
        if (sphere_intersect(r, spheres[i], &t) && t < best_t) {
            best_t = t;
            best_i = i;
        }
    }

    if (best_i == -1) {
        Vec3 d = normalize(r.direction);
        float t = 0.5f * (d.y + 1.0f);
        return add(mul((Vec3){1,1,1}, 1-t), mul((Vec3){0.5,0.7,1}, t));
    }

    Vec3 p = ray_at(r, best_t);
    Vec3 n = normalize(sub(p, spheres[best_i].center));

    if (depth <= 0) return spheres[best_i].color;

    Vec3 target = add(p, add(n, (Vec3){(rand()%1000-500)/500.f, (rand()%1000-500)/500.f, (rand()%1000-500)/500.f}));
    Ray scattered = ray_create(p, sub(target, p));
    Vec3 col = trace(scattered, spheres, n_spheres, depth-1);
    return mul(mul(spheres[best_i].color, 0.5f), col);
}

int main() {
    fprintf(stderr, "Creating high-resolution image: %dx%d\n", WIDTH, HEIGHT);
    fprintf(stderr, "This will be downsampled with ffmpeg after rendering\n");
    fprintf(stderr, "Rendering high-resolution image...\n");

    Sphere spheres[] = {
        {{0, -1000.5f, -1}, 1000, {0.8f, 0.8f, 0.8f}, 0},
        {{2, 0, -1}, 0.5f, {0.8f, 0.3f, 0.3f}, 1},
        {{0, 0, -1}, 0.5f, {0.8f, 0.8f, 0.3f}, 1},
        {{-2, 0, -1}, 0.5f, {0.3f, 0.3f, 0.8f}, 1},
    };
    int n_spheres = 4;

    FILE *f = fopen("image.ppm", "w");
    fprintf(f, "P3\n%d %d\n255\n", WIDTH, HEIGHT);

    for (int y = 0; y < HEIGHT; y++) {
        if (y % 60 == 0) fprintf(stderr, "Progress: %.1f%%\n", 100.0f * y / HEIGHT);

        for (int x = 0; x < WIDTH; x++) {
            Vec3 color = {0, 0, 0};
            for (int s = 0; s < SAMPLES; s++) {
                float u = (x + (rand()%1000)/1000.f) / WIDTH;
                float v = (HEIGHT - y + (rand()%1000)/1000.f) / HEIGHT;
                float vfov = 45.0f;
                float h = tanf(vfov * 3.14159f / 360.0f);
                float aspect = (float)WIDTH / HEIGHT;
                Vec3 origin = {0, 0, 0};
                Vec3 dir = {(2*aspect*h*u - aspect*h), (2*h*v - h), -1};
                Ray r = ray_create(origin, dir);
                Vec3 c = trace(r, spheres, n_spheres, MAX_DEPTH);
                color = add(color, c);
            }
            color = mul(color, 1.0f / SAMPLES);
            int ir = (int)(255 * sqrtf(color.x));
            int ig = (int)(255 * sqrtf(color.y));
            int ib = (int)(255 * sqrtf(color.z));
            fprintf(f, "%d %d %d\n", ir, ig, ib);
        }
    }

    fprintf(stderr, "Rendering complete\n");
    fprintf(f, "");
    fclose(f);
    fprintf(stderr, "Wrote image to image.ppm\n");
    fprintf(stderr, "Done.\n");

    return 0;
}
